import re
def rw(p, f):
    s=open(p).read(); s=f(s); open(p,'w').write(s)

def helpers(s):
    i=s.index("class SettingsCase")
    return s[:i]+'''class SettingsCase(unittest.TestCase):
    """Starts every test from the fallback settings with caching off, so that
    results from one test are never reused by another. `self.conf` is the
    Settings under test; `self.configure(**values)` replaces it with one that
    also has the given values."""

    def setUp(self) -> None:
        self.values = {"cache_enabled": False}
        self.conf = settings.make(**self.values)

    def configure(self, **values) -> settings.Settings:
        merged = {**self.values, **values}
        self.conf = settings.make(**merged)
        self.values = merged
        return self.conf
'''
rw('helpers.py', helpers)

def common(s):
    s=s.replace("settings.configure(","self.configure(")
    for fn in ["make_request","quote_all","cheapest","run_batch","render_quotes","render_batch","registry.enabled","zones.zone_for","zones.zones_from"]:
        s=re.sub(r"(?<![\w.])"+re.escape(fn)+r"\(", fn+"(@@", s) if "." not in fn else s.replace(fn+"(", fn+"(@@")
    return s
for p in ['test_quotes.py','test_zones.py','test_output.py','test_batch.py']:
    def f(s):
        s=common(s)
        s=s.replace("def make_request(@@","def make_request(")  # none
        return s
    rw(p,f)
